INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('01dc980f-ae8e-4740-8f66-cb98e7d0875f', 'Bake It Till You Make It', 'Bake It Till You Make It aims to cultivate an inclusive community for students to share and expand their love of baking!', 'Bake It Till You Make It is an organization to bring students together who have an interest or passion for baking. Whether you''re a seasoned pastry chef or a novice in the kitchen, our club provides a space to explore the art of baking, share delicious recipes, and foster a love for all things sweet. Come join us, and let''s bake memories together!', '140', 'FALSE', 'fallSpring', 'application', '00000000-0000-0000-0000-000000000000');
INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('15b8b22a-515f-4c5e-96c7-6add82a0822d', 'Baltic Northeastern Association', 'The Baltic Northeastern Association serves as a home away from home for students from the Baltic countries, as well as an opportunity to share Baltic culture with interested students. ', 'The Baltic Northeastern Association serves as a home away from home for students from the Baltic countries, as well as an opportunity to share Baltic culture with interested students. We will host weekly meetings that can range from cooking sessions, discussions of Baltic culture and language, sharing Baltic traditional dancing and music, and more. ', '149', 'TRUE', 'fall', 'unrestricted', '00000000-0000-0000-0000-000000000000');
INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('aa897618-98b1-4fbe-82db-42af863fe955', 'Bangladeshi Organization of Networking, Diversity, Heritage, Unity and Support', 'The BONDHUS is dedicated to fostering a sense of home for Bangladeshi students and those interested in Bangladeshi culture, as well as celebrating the rich cultural heritage of Bangladesh.', 'The BONDHUS is dedicated to fostering a sense of home for Bangladeshi students and those interested in Bangladeshi culture. We strive to provide mentorship, build cultural awareness, and offer assistance with college admissions, including hosting events in Bangladesh related to Northeastern University. Our mission is to create an inclusive community that celebrates and promotes the rich heritage of Bangladesh while providing support and growth opportunities for our members. Our target membership includes Bangladeshi international undergraduates and graduates, Bangladeshi diaspora-born undergraduates and graduates, and non-Bangladeshi undergraduates and graduates interested in our culture and mission. We plan to host a wide range of events and initiatives, including:INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('34f55fcb-80f9-4b0b-a9c1-e440fe2e057c', 'Binky Patrol', 'Binky Patrol is club that makes blankets by hand to donate to children in hospitals and shelters', 'Binky Patrol is a club that makes blankets by hand to donate to children in hospitals and shelters - if you want to get involved, join the slack with the link below!INSERT INTO "clubs" ("id", "name", "preview", "description", "num_members", "is_recruiting", "recruitment_cycle", "recruitment_type", "parent") VALUES ('52de52ab-66bd-496e-b758-945b8682e58c', 'Biokind Analytics Northeastern', 'Biokind Analytics Northeastern brings together undergraduate data scientists and statisticians across the world to apply classroom learning for meaningful, positive societal impact in their communities.', 'Biokind Analytics Northeastern is a local chapter of the larger nonprofit organization, Biokind Analytics. The club aims to provide Northeastern students with the opportunity to apply data analysis skills and learnings to further the mission of local healthcare non-profit organizations in the Boston region. Our goal is to promote the development of relationships between Northeastern students and healthcare non-profits to better contribute to our local community. ', '396', 'TRUE', 'always', 'application', '00000000-0000-0000-0000-000000000000');
